-- The faster launch plan (8 October, evening): Dawid works 8 hours a day including weekends, and
-- Pixel and Analytics are already in the CRM. iOS goes public as soon as Apple approves it
-- (about 15 October), Android after Google's 14-day closed test (about 29 October), and the
-- premiere with ads, newsletter and influencers moves from 16 to 2 November.
-- Only what is still as the plan wrote it changes: a task moved, renamed or reworded on the
-- board keeps its own date and words.

update public.crm_items c
set due = case when c.due = v.old_due then v.new_due else c.due end,
    title = case when c.title = v.old_title then v.new_title else c.title end,
    body = case when v.old_body <> '' and position(v.old_body in c.body) = 1
                then v.new_body || substr(c.body, length(v.old_body) + 1) else c.body end
from (values
