-- Pixel and Analytics are done: the measuring task is only the MailerLite automations now.
update public.crm_items
set data = data || '{"hours": 1.5}', body = replace(body, 'Czas: ok. 3 h.', 'Czas: ok. 1,5 h.')
where data->>'plan' = 'premiera-2026' and data->>'key' = 'f1-measure';
